def compute_output_spec(self, x, key):
    if not isinstance(key, (int, slice)):
        raise ValueError(
            "Only scalar int or slice keys are supported at this time. Cannot "
            f"process key {key}"
        )
    if len(x.shape) == 0:
        raise ValueError(
            f"Too many indices for array: array is scalar "
            f"but index {key} was requested. A scalar array "
            "cannot be indexed."
        )
    if isinstance(key, slice):
        if x.shape[0] is not None and (key.start is not None and key.start >= x.shape[0]):
            raise ValueError(
                f"Array has shape {x.shape} "
                f"but out-of-bound index {key.start} was requested."
            )
        if key.stop is not None and key.stop > x.shape[0]:
            raise ValueError(
                f"Array has shape {x.shape} "
                f"but out-of-bound index {key.stop} was requested."
            )
    else:
        if x.shape[0] is not None and key >= x.shape[0]:
            raise ValueError(
                f"Array has shape {x.shape} "
                f"but out-of-bound index {key} was requested."
            )
    return KerasTensor(x.shape[1:], dtype=x.dtype)
